package com.johnny.hotel.finance;import com.johnny.hotel.businessdate.BusinessDateService;import com.johnny.hotel.exception.BusinessException;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor public class RevenueRecognitionService {private final RevenueRecognitionMapper db;private final BusinessDateService dates;private final Clock clock;
 @Transactional(propagation=Propagation.REQUIRES_NEW) public List<RevenueRecognition> recognize(LocalDate date){dates.closingPostingDate(date);db.recognizeFolioItems(date,date,LocalDateTime.now(clock));return db.byRecognitionDate(date);}
 @Transactional(propagation=Propagation.REQUIRES_NEW) public DailyFinancialSummary summarize(LocalDate date,Long run){dates.closingPostingDate(date);var old=db.summary(date);if(old!=null){if(!run.equals(old.getNightAuditRunId()))throw new BusinessException("Daily summary already belongs to another Night Audit run");return old;}if(db.insertSummary(date,run,LocalDateTime.now(clock))!=1)throw new BusinessException("Daily financial summary could not be created");return db.summary(date);}
 public DailyFinancialSummary summary(LocalDate date){return db.summary(date);}public List<DailyFinancialSummary> summaries(){return db.summaries();}
}
